head.script:
scwin.onpageload = function () {
    /* ReferenceError 는 화면에 아무 표시가 없어 콘솔로만 드러난다.
       비동기 경로에서 던져지는 경우까지 잡기 위해 전역 트랩을 건다. */
    window.__errs = [];
    window.addEventListener("error", function (e) {
        window.__errs.push(e.message);
        console.error("[UNCAUGHT] " + e.message);
    });
};

/*
 * [후속 이슈] multipleDataListDownload 호출 공통 러너
 *   증상 : ReferenceError: isProcessMsgShown is not defined
 *   원인 : WAEA-1043 에서 추가한 processMsgScope / isProcessMsgShown 지역변수 선언이
 *          multipleDataListDownload() 가 아닌 multipleExcelDownload() 에 반영됨
 *   → showProcess 설정과 확장자를 바꿔가며 호출해야 검증 범위가 채워진다.
 *     showProcess 에 null 을 넘기면 common 에 키 자체를 넣지 않는다(= 미지정 기본값).
 */
scwin.runDataListDwn = function (fileName, showProcess) {
    var common = {
        fileName : fileName,
        multipleSheet : true
    };
    if (showProcess !== null) {
        common.showProcess = showProcess;
    }

    var options = {
        common : common,
        excelInfo : [
            {
                dataListId : "dlt_sample",
                sheetName : "첫번째 sheet",
                startRowIndex : 3,
                startColumnIndex : 0,
                wframeId : $p.getFrameId()
            }
        ]
    };

    var label = fileName + " / showProcess=" + (showProcess === null ? "미지정" : showProcess);
    try {
        WebSquare.util.multipleDataListDownload(options);
        console.log("[호출 성공] " + label);
    } catch (e) {
        console.error("[호출 실패] " + label + " → " + e.name + ": " + e.message);
    }
};

scwin.btn_dl_xlsx_true_onclick    = function () { scwin.runDataListDwn("excel_dataList.xlsx", true);  };
scwin.btn_dl_xlsx_false_onclick   = function () { scwin.runDataListDwn("excel_dataList.xlsx", false); };
scwin.btn_dl_xlsx_default_onclick = function () { scwin.runDataListDwn("excel_dataList.xlsx", null);  };
scwin.btn_dl_xls_true_onclick     = function () { scwin.runDataListDwn("excel_dataList.xls",  true);  };

/*
 * [정상 1] 그리드뷰 엑셀다운로드
 * processMsg가 정상 표시/종료됨 (고객사 환경에서도 정상 동작 케이스)
 */
scwin.btn_gridExcel_onclick = function () {
    grd_sample.advancedExcelDownload({ fileName : "excel_gridView.xlsx" });
};

/*
 * [정상 2] 멀티그리드뷰 엑셀다운로드
 * processMsg가 정상 표시/종료됨 (고객사 환경에서도 정상 동작 케이스)
 */
scwin.btn_multiGridDwn_onclick = function () {
    var options = {
        common : {
            fileName : "excel_multiGrid.xlsx",
            multipleSheet : true
        },
        excelInfo : [
            {
                gridId : "grd_sample",
                sheetName : "첫번째 sheet",
                wframeId : $p.getFrameId()
            }
        ]
    };
    WebSquare.util.multipleExcelDownload(options);
};

/*
 * [현상 재현] 멀티데이타리스트 엑셀다운로드
 * 현상 1: processMsg가 창 내부가 아닌 전체 화면(top)에 표시됨 (processMsgFrame:"true" 미적용)
 * 현상 2: 다운로드 완료 후에도 processMsg가 사라지지 않음
 * ※ wframeId 미지정 시 top 영역에서 dataList를 찾지 못해
 *    "Cannot read properties of undefined (reading 'getDataLength')" TypeError 발생
 */
scwin.btn_dataListDwn_onclick = function () {
    var options = {
        common : {
            fileName : "excel_dataList.xlsx",
            showProcess : true,
            multipleSheet : true
        },
        excelInfo : [
            {
                dataListId : "dlt_sample",
                sheetName : "첫번째 sheet",
                startRowIndex : 3,
                startColumnIndex : 0,
                wframeId : $p.getFrameId()
            }
        ]
    };
    WebSquare.util.multipleDataListDownload(options);
};
